def cmd_expense_edit(args):
    data = load()
    expense_id = parse_id(args.id, "expense")
    expense = next((e for e in data["expenses"] if e["id"] == expense_id), None)
    if expense is None:
        raise KittyError(f"there is no expense with ID {expense_id}")
    split_given = any(v is not None for v in (args.among, args.exact, args.shares, args.percent))
    if split_given is False and all(
        v is None for v in (args.payer, args.amount, args.description, args.date, args.category, args.currency)
    ):
        raise KittyError("nothing to change; give at least one option (see: python3 -m kitty expense edit --help)")

    updates = {}
    if args.payer is not None:
        updates["payer"] = require_member(data, args.payer)
    if args.description is not None:
        description = args.description.strip()
        if not description:
            raise KittyError("description cannot be empty")
        updates["description"] = description
    if args.category is not None:
        category = args.category.strip().lower()
        if not category:
            raise KittyError("category cannot be empty")
        updates["category"] = category
    if args.date is not None:
        updates["date"] = parse_date(args.date)

    amount = parse_money(args.amount) if args.amount is not None else Decimal(expense["amount"])
    currency = parse_currency(args.currency) if args.currency is not None else expense["currency"]
    # Keep the rate the expense was recorded with unless the currency changes.
    rate = rate_for(data, currency) if currency != expense["currency"] else Decimal(expense["rate"])
    money_changed = amount != Decimal(expense["amount"]) or currency != expense["currency"]

    if split_given or money_changed:
        if split_given:
            weights = split_weights(data, args, amount)
        else:
            weights = [(n, Decimal(1)) for n in data["members"] if n in expense["shares"]]
        base_amount = to_base(amount, rate)
        shares = allocate(base_amount, weights)
        updates.update({
            "amount": fmt(amount),
            "currency": currency,
            "rate": str(rate),
            "base_amount": fmt(base_amount),
            "shares": {name: fmt(shares[name]) for name in data["members"] if name in shares},
        })

    expense.update(updates)
    save(data)
    print(f"Updated expense {expense_id} ({expense['description']}).")


